query.base:
TS metrics-gcp.bigquery.otel-*
// Lowest-latency cost signal: statement_scanned_bytes_billed (DELTA, ~3 minute publish delay).
// Capacity (Editions) projects are billed for slots, not bytes, and normally report ~0 here.
| WHERE resource.attributes.gcp.resource_type == "bigquery_project"
// Stage 1: bytes billed per project per minute. DELTA amounts are additive, so SUM is exact
// across fragmented TSIDs, locations, priorities and statement types.
// `heartbeat` references query/count and job/num_in_flight, which GCP reports every minute (as 0 when idle),
// so a row exists for every published minute even when nothing was billed (billed is then null -> 0).
| STATS billed = SUM(SUM_OVER_TIME(`metrics.bigquery.googleapis.com/query/statement_scanned_bytes_billed`)),
        heartbeat = SUM(COUNT_OVER_TIME(`metrics.bigquery.googleapis.com/query/count`)) + SUM(COUNT_OVER_TIME(`metrics.bigquery.googleapis.com/job/num_in_flight`))
    BY @timestamp = TBUCKET(1 minute), resource.attributes.project_id
| EVAL billed = COALESCE(billed, 0)
// Split the 26-hour rule window into comparison periods (relative to rule execution time):
//   recent    = the last full hour, ending 5 minutes ago (skips not-yet-published minutes)
//   yesterday = the same hour 24 hours earlier (absorbs daily scheduled jobs)
//   baseline  = everything before the recent hour (hourly average)
| EVAL period = CASE(
    @timestamp >= NOW() - 65 minutes AND @timestamp < NOW() - 5 minutes, "recent",
    @timestamp >= NOW() - 5 minutes, "unpublished",
    "baseline")
| EVAL same_hour_yesterday = @timestamp >= NOW() - 1505 minutes AND @timestamp < NOW() - 1445 minutes
| STATS recent_bytes_billed = SUM(billed) WHERE period == "recent",
        baseline_bytes_billed = SUM(billed) WHERE period == "baseline",
        yesterday_bytes_billed = SUM(billed) WHERE same_hour_yesterday,
        // Published minutes per period. heartbeat must stay referenced (COUNT(heartbeat)),
        // otherwise ES|QL prunes it and silently drops the minutes without billing.
        recent_minutes = COUNT(heartbeat) WHERE period == "recent",
        baseline_minutes = COUNT(heartbeat) WHERE period == "baseline",
        yesterday_minutes = COUNT(heartbeat) WHERE same_hour_yesterday
    BY resource.attributes.project_id

breach.segment:
// Customise: data coverage required before comparing. A collector or publishing gap must not
// shrink the reference: recent >= 45 of 60 minutes, baseline >= 1200 of its 1495 minutes
// (~80%, so a new project needs ~a day of history), same hour yesterday >= 45 of 60 minutes
WHERE recent_minutes >= 45 AND baseline_minutes >= 1200 AND yesterday_minutes >= 45
// Hourly average over published baseline minutes only (not elapsed time)
| EVAL baseline_hourly_bytes = COALESCE(baseline_bytes_billed, 0) * 60.0 / baseline_minutes,
       yesterday_bytes_billed = COALESCE(yesterday_bytes_billed, 0),
       recent_bytes_billed = COALESCE(recent_bytes_billed, 0)
| EVAL reference_bytes = GREATEST(baseline_hourly_bytes, yesterday_bytes_billed)
// Customise: minimum spend worth alerting on (default 1 TiB billed in the hour)
| WHERE recent_bytes_billed >= 1099511627776
// Customise: spike multiplier versus the larger of the 24h hourly average and the same hour yesterday
| WHERE recent_bytes_billed >= 3 * reference_bytes
| EVAL recent_tib_billed = ROUND(recent_bytes_billed / 1099511627776.0, 2),
       reference_tib_billed = ROUND(reference_bytes / 1099511627776.0, 2),
       spike_ratio = CASE(reference_bytes > 0, ROUND(recent_bytes_billed / reference_bytes, 1), NULL)
| KEEP resource.attributes.project_id, recent_tib_billed, reference_tib_billed, spike_ratio, recent_bytes_billed, baseline_hourly_bytes, yesterday_bytes_billed, recent_minutes, baseline_minutes, yesterday_minutes
| SORT recent_bytes_billed DESC
| LIMIT 50
